select from lab_report_instance where del_flag='0' and period=#{period}and biz_line=#{bizLine}
and lifecycle_status in ('FINALIZED','SUPERSEDED') and sensitive_flag='0' and (biz_line=#{actorBizLine} or biz_line='ALL')
and sensitive_flag='0' order by period desc,template_code,revision_no desc,id desc
